/bin/zsh -lc "python -c 'import pandas as pd,numpy as np; d=pd.read_csv(\"data/a1b_north_america_annual.csv\"); s=d[(d.latitude==15)&(d.longitude==225)].sort_values(\"year\"); y=s.year.to_numpy(float); z=s.air_temperature.to_numpy(float); 
for a in range(0,10):
 for b in range(230,241):
  t=y[a:b]-2000; X=np.c_[np.ones(len(t)),t,t*t]; c=np.linalg.lstsq(X,z[a:b],rcond=None)[0];
  if abs(c[2]-0.000131003)<1e-6: print(a,b,c)
'"

